from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb = load_workbook(path, data_only=False)
wbv = load_workbook(path, data_only=True)
print('Sheets:', wb.sheetnames)
for s in ['Task','Data']:
    ws=wb[s]
    print(f'\nSheet {s}: max_row={ws.max_row}, max_col={ws.max_column}')

ws=wb['Task']; wsv=wbv['Task']
print('\n=== Task rows 1-55 cols A-L (formula_mode | cached_value if different) ===')
for r in range(1,56):
    vals=[]
    for c in range(1,13):
        cell=ws.cell(r,c); v=cell.value; cv=wsv.cell(r,c).value
        if v is None and cv is None:
            vals.append('')
        elif v != cv and isinstance(v,str) and v.startswith('='):
            vals.append(f'{get_column_letter(c)}{r}:{v} [cached={cv!r}]')
        else:
            vals.append(f'{get_column_letter(c)}{r}:{v!r}')
    print(' | '.join(vals))

ws=wb['Data']; wsv=wbv['Data']
